const rnd=(min,max)=>min+Math.floor(Math.random()*(max-min+1));
const pick=list=>list[Math.floor(Math.random()*list.length)];
export function sample(list, amount) {return list.map(value=>({value,sort:crypto.getRandomValues(new Uint32Array(1))[0]})).sort((a,b)=>a.sort-b.sort).slice(0,amount).map(x=>x.value);}
const options=(correct,wrongs)=>{const unique=[...new Set(wrongs.map(String))].filter(w=>w!==String(correct)).slice(0,wrongs.length>=3?3:2);const choices=sample([String(correct),...unique],unique.length+1);return {choices,answer:choices.indexOf(String(correct))};};
const nearby=(n,spread=[1,2,3,-1,-2,-3,10,-10])=>sample(spread,3).map(d=>n+d);

